/** Reports whether a promise settled after pending work had a chance to run. */
async function isSettled(promise) {
  let settled = false;
  promise.then(
    () => {
      settled = true;
    },
    () => {
      settled = true;
    }
  );
  await new Promise((resolve) => setTimeout(resolve, 0));
  return settled;
}

